import{_ as n,o as s,c as e,a2 as o}from"./chunks/framework.B7YvHKtj.js";const g=JSON.parse('{"title":"双模型协作流水线调优指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/advanced/dual_model.md","filePath":"zh/docs/advanced/dual_model.md"}'),l={name:"zh/docs/advanced/dual_model.md"};function i(t,a,r,c,d,p){return s(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="双模型协作流水线调优指南" tabindex="-1">双模型协作流水线调优指南 <a class="header-anchor" href="#双模型协作流水线调优指南" aria-label="Permalink to &quot;双模型协作流水线调优指南&quot;">​</a></h1><p>在传统的 AI 字幕插件中，单模型逐行翻译通常面临两难困境：要么单句翻译速度慢导致音画不同步，要么分句翻译缺乏上下文导致前后人名、语气、专有名词频繁错乱（例如同一个角色前一分钟叫“汤姆”，后一分钟被翻译为“小明”）。</p><p><strong>CoWatcher 创新性地采用了双模型分工流水线（Dual-Model Architecture）</strong>。</p><hr><h2 id="_1-双模型工作原理" tabindex="-1">1. 双模型工作原理 <a class="header-anchor" href="#_1-双模型工作原理" aria-label="Permalink to &quot;1. 双模型工作原理&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[视频播放器字幕流]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> ┌──────────────────────────┐</span></span>
<span class="line"><span> │  Translation Model 翻译模型 │ ◄── 注入剧集术语表与上下文记忆</span></span>
<span class="line"><span> └─────────────┬────────────┘</span></span>
<span class="line"><span>               │ 毫秒级流式批量产出</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>       [实时播放器字幕渲染]</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>       (异步后台审计与记忆沉淀)</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span> ┌──────────────────────────┐</span></span>
<span class="line"><span> │  Supervisor Model 监督模型 │ ──► 维护人名/地名一致性、提取剧情生词</span></span>
<span class="line"><span> └──────────────────────────┘</span></span></code></pre></div><ol><li><p><strong>Translation Model（翻译模型）</strong>：</p><ul><li><strong>定位</strong>：轻量、低延迟、高并发。</li><li><strong>职责</strong>：执行超前分批翻译（Lookahead Batching），在用户播放到该时间点前 10~30 秒提前将句子翻译完毕，确保播放时字幕零等待。</li><li><strong>推荐</strong>：<code>translategemma:4b</code>（本地 Ollama）或 <code>deepseek/deepseek-chat</code> / <code>google/gemini-2.0-flash-001</code>（云端）。</li></ul></li><li><p><strong>Supervisor Model（监督模型）</strong>：</p><ul><li><strong>定位</strong>：长文本、强推理、擅长上下文总结。</li><li><strong>职责</strong>：在后台异步分析整集剧集的剧情大纲、角色出场、专有名词映射，动态生成一致性术语表（Glossary），并对疑难俚语进行审核校对。</li><li><strong>推荐</strong>：<code>gemma4:e4b</code> / <code>qwen2.5:7b</code>（本地）或 <code>google/gemini-2.0-flash-001</code> / <code>anthropic/claude-3.5-haiku</code>（云端）。</li></ul></li></ol><hr><h2 id="_2-关键参数性能调优" tabindex="-1">2. 关键参数性能调优 <a class="header-anchor" href="#_2-关键参数性能调优" aria-label="Permalink to &quot;2. 关键参数性能调优&quot;">​</a></h2><p>在 CoWatcher 弹窗面板的 <strong>Dual-Model Pipeline Tuning</strong> 区域可以根据你的硬件和网络调节以下参数：</p><h3 id="batch-size-批处理大小" tabindex="-1">Batch Size（批处理大小） <a class="header-anchor" href="#batch-size-批处理大小" aria-label="Permalink to &quot;Batch Size（批处理大小）&quot;">​</a></h3><ul><li><strong>推荐值</strong>：<code>5</code> ~ <code>10</code></li><li><strong>说明</strong>：将多少行字幕合并为一个请求发送给大模型。数值过小会导致网络请求频繁；数值过大可能会增加单次等待时间。</li></ul><h3 id="lookahead-window-超前预翻译窗口" tabindex="-1">Lookahead Window（超前预翻译窗口） <a class="header-anchor" href="#lookahead-window-超前预翻译窗口" aria-label="Permalink to &quot;Lookahead Window（超前预翻译窗口）&quot;">​</a></h3><ul><li><strong>推荐值</strong>：<code>15</code> ~ <code>30</code> 秒</li><li><strong>说明</strong>：根据当前播放进度，提前将未来多少秒的字幕翻译完成并缓存到本地 IndexedDB。</li></ul><h3 id="max-concurrency-最大并发请求数" tabindex="-1">Max Concurrency（最大并发请求数） <a class="header-anchor" href="#max-concurrency-最大并发请求数" aria-label="Permalink to &quot;Max Concurrency（最大并发请求数）&quot;">​</a></h3><ul><li><strong>本地 Ollama（显卡）</strong>：建议设为 <code>1</code>。避免多请求争抢显存引发显存溢出（OOM）或排队阻塞。</li><li><strong>云端 OpenRouter</strong>：建议设为 <code>2</code> ~ <code>4</code>。云端服务器支持高并发，可成倍加快整季预加载速度。</li></ul>`,16)])])}const u=n(l,[["render",i]]);export{g as __pageData,u as default};
